package vn.hust.restaurant.service;import java.sql.*;import java.time.*;import vn.hust.restaurant.model.*;import vn.hust.restaurant.repository.ReportRepository;public class ReportService{private final ReportRepository r;public ReportService(ReportRepository r){this.r=r;}public DashboardStats dashboard()throws SQLException{return r.dashboard();}public ReportTable revenue(LocalDate f,LocalDate t)throws SQLException{return r.revenue(f,t);}public ReportTable top(LocalDate f,LocalDate t)throws SQLException{return r.topItems(f,t);}public ReportTable low()throws SQLException{return r.lowStock();}public ReportTable receipts(LocalDate f,LocalDate t)throws SQLException{return r.stockReceipts(f,t);}}
